    {"대지": "서론", "내용": "바울이 디모데를 부르는 호칭은 단순한 인사가 아닌 깊은 애정의 표현이다. 믿음 안에서 참 아들이란 말은 복음이 만든 새로운 관계를 선언한다", "예화_적용": "혈연이 아닌 믿음으로 맺어진 가족이 때로 더 깊다. 바울과 디모데의 관계가 그 증거이다"},
    {"대지": "1대지: 믿음이 만든 가족 (영적 혈연)", "내용": "디모데는 바울의 육신의 아들이 아니었다. 그러나 복음을 통해 참 아들이 되었다. 믿음은 새로운 가족을 창조한다", "예화_적용": "입양된 자녀가 친자녀와 다름없이 사랑받듯 믿음으로 맺어진 자녀는 동일한 사랑을 받는다"},
    {"대지": "2대지: 은혜와 긍휼과 평강 (삼중 축복)", "내용": "바울은 일반 인사인 은혜-평강에 긍휼을 더한다. 목회자가 특별히 필요로 하는 것이 긍휼이다. 연약함 속에 감당하는 사역은 하나님의 긍휼 없이 불가능하다", "예화_적용": "무거운 짐을 진 사람에게는 더 많은 쉼과 위로가 필요하다. 사역의 무게를 진 자에게는 하나님의 긍휼이 필요하다"},
    {"대지": "3대지: 하나님과 그리스도에게서 함께 (공동 출처)", "내용": "축복의 출처는 하나님 아버지와 그리스도 예수 우리 주이시다. 성부와 성자가 함께 베푸시는 축복은 어떤 상황에서도 마르지 않는다", "예화_적용": "두 샘에서 함께 흘러나오는 물은 마르지 않는다. 성부와 성자의 공동 축복은 성도의 영원한 공급이다"},
    {"대지": "결론", "내용": "바울이 디모데에게 전한 축복은 오늘 우리에게도 전해진다. 믿음의 가족 안에서 은혜와 긍휼과 평강이 흐른다. 이 축복을 받고 또 다른 이에게 흘려보내자", "예화_적용": "받은 은혜는 흘려보낼 때 더 풍성해진다. 영적 아버지가 된 바울처럼 우리도 영적 자녀를 세우는 삶을 살자"}
