    {"상황": "목회의 무게에 짓눌린 사역자", "성경원리": "바울이 디모데에게 특별히 긍휼을 기원한 것은 목회자에게 긍휼이 가장 필요하기 때문이다. 하나님의 긍휼이 연약한 자를 붙드신다", "실제적용": "자기의 능력에 의존하지 말고 매일 하나님의 긍휼을 구하도록 안내하며 동역자와 함께 짐을 나누도록 권면하라"}
