    {"원어": "πιστόν (피스톤)", "의미_문법": "충성된 - 형용사 남성 단수 대격. 믿을 만한, 신실한", "설교포인트": "주님은 바울을 충성된 자로 여기셨다. 이는 바울의 자격이 아닌 주님의 은혜로운 판단이다"},
    {"원어": "διακονίαν (디아코니안)", "의미_문법": "직분 - 명사 여성 단수 대격. 섬김, 봉사", "설교포인트": "직분은 섬김이다. 높아지는 것이 아닌 낮아져 섬기는 자리이다"}
