    {"상황": "자신이 쓸모없다고 느끼는 분", "성경원리": "주님은 가장 부족한 자를 부르시고 충성된 자로 여기신다. 자격은 부르심 전이 아닌 후에 주어진다", "실제적용": "자신을 바라보지 말고 부르시는 주님을 바라보도록 돕고 작은 섬김부터 시작하여 은혜 안에서 자라가도록 안내하라"}
