    {"항목": "다메섹 도상의 회심", "내용": "바울은 다메섹 도상에서 부활하신 그리스도를 만나 회심했다. 핍박자에서 사도로 변화된 극적인 사건은 기독교 역사의 전환점이었다", "목회적활용": "회심은 근본적 방향 전환이다. 핍박하던 자를 예배하는 자로 만드시는 분은 주님이시다"}
