    {"구절": "엡 1:7-8", "연결점": "그의 은혜의 풍성함을 따라 우리에게 넘치게 하사 — 넘치는 은혜", "구분": "신약"},
    {"구절": "갈 5:6", "연결점": "사랑으로써 역사하는 믿음 — 믿음과 사랑의 통합", "구분": "신약"},
    {"구절": "살전 1:3", "연결점": "믿음의 역사와 사랑의 수고와 소망의 인내 — 믿음-사랑의 쌍", "구분": "신약"},
    {"구절": "고후 9:8", "연결점": "하나님이 능히 모든 은혜를 너희에게 넘치게 하시나니 — 넘치는 은혜", "구분": "신약"},
    {"구절": "요 1:16", "연결점": "우리가 다 그의 충만한 데서 받으니 은혜 위에 은혜러라 — 은혜의 연속", "구분": "신약"},
    {"구절": "벧전 1:22", "연결점": "형제를 사랑하기에 이르렀으니 — 은혜의 결과로서의 사랑", "구분": "신약"},
    {"구절": "시 103:11-12", "연결점": "그의 인자하심이 크심이여 동이 서에서 먼 것같이 우리 죄과를 멀리 옮기셨으며 — 풍성한 은혜의 비유", "구분": "구약"}
