    {"항목": "기약이 이른 것의 의미", "내용": "기약(καιροῖς ἰδίοις)은 하나님의 정하신 때이다. 갈라디아서 4:4의 때가 찬 경륜과 연결된다. 구속사의 정점에 그리스도의 대속이 있었다", "목회적활용": "하나님은 자신의 때에 일하신다. 우리의 급한 마음이 아닌 하나님의 정하신 때가 있다"}
