    {"대지": "결론", "내용": "우리를 위해 드려진 속전을 기억하자. 이 값을 깨달을 때 감사가 넘친다. 감사의 삶으로 그 속전에 응답하자", "예화_적용": "값 치른 자만이 값의 의미를 안다. 값 받은 자도 그 값의 무게를 알아야 한다"}
