    {"교리": "진리 안의 확신", "설명": "사역자는 자신의 부르심에 대한 분명한 확신을 가져야 한다. 참말이요 거짓말이 아니라는 확신이 사역의 기초이다", "관련구절": "갈 1:1, 고전 9:1, 롬 9:1"}
