    {"항목": "동시대 유대 및 헬라 윤리가", "내용": "유대 랍비들과 헬라 철학자들도 여성의 화려한 치장을 비판했다. 바울의 가르침은 당시 도덕가들의 공통 관심사와도 맞닿아 있었다. 다만 기독교는 이를 신앙의 차원으로 끌어올렸다", "목회적활용": "일반 은총적 지혜와 특별계시의 지혜가 조화를 이룰 수 있다"}
