    {"항목": "에베소의 특수 상황", "내용": "에베소 교회는 거짓 교사들의 위협 아래 있었고 일부 여성들이 이에 영향을 받은 정황이 있다(딤전 5:13-15). 이 맥락에서 가르침과 권위 행사의 금지가 이해될 수 있다", "목회적활용": "성경 본문은 문맥 안에서 이해되어야 한다. 절대화와 상대화의 극단을 모두 피해야 한다"}
