    {"영어원문": "Women are not excluded from all speaking in the church, but from that public teaching which is an act of authority.", "한국어번역": "여성은 교회에서 모든 말하는 것에서 제외된 것이 아니라 권위 행위인 공적 가르침에서 제외된다.", "핵심통찰": "모든 말하기가 아닌 권위적 가르침이 문제이다"}
