    {"원어": "σωφροσύνης (소프로쉬네스)", "의미_문법": "정숙함 - 명사 여성 단수 속격. 절제, 건전한 판단", "설교포인트": "이 단어는 2장에서 세 번 나온다(9, 15절). 여성의 덕을 강조한다"}
