    {"교리": "믿음의 담대함", "설명": "하나님 앞에 나아가는 담대함은 그리스도 안에 있는 믿음에서 나온다. 충성된 섬김이 이 담대함을 강화한다", "관련구절": "히 4:16, 엡 3:12, 요일 3:21"}
