    {"대지": "결론", "내용": "지금 있는 자리에서 잘 섬기자. 보이지 않는 곳에서의 충성이 보이는 축복으로 돌아온다", "예화_적용": "작은 섬김의 씨앗이 큰 열매를 맺는다"}
