    {"대지": "4대지: 만국에 전파되심 (선교)", "내용": "복음이 모든 민족에게 전파되었다. 한 사람의 이야기가 온 세계의 이야기가 되었다", "예화_적용": "한 씨가 온 땅을 덮었다"},
    {"대지": "5대지: 세상에서 믿은 바 되심 (수용)", "내용": "세상이 그분을 믿었다. 전파된 복음이 수용되는 것이 선교의 완성이다", "예화_적용": "말씀이 심령에 뿌리를 내릴 때 복음이 완성된다"},
    {"대지": "6대지: 영광 중에 올라가심 (영광)", "내용": "그리스도는 영광 중에 들림을 받으셨다. 그 영광이 교회의 최종 소망이다", "예화_적용": "시작의 영광이 끝의 영광과 만난다"},
    {"대지": "결론", "내용": "이 경건의 비밀이 우리 교회의 고백이다. 우리도 이 놀라운 복음을 증거하는 자들이 되자", "예화_적용": "크도다 경건의 비밀이여 오늘도 우리는 이 비밀을 고백한다"}
